svg.script:
(function(){
var X='http://www.w3.org/1999/xhtml';
document.createElement=function(n){return document.createElementNS(X,String(n).toLowerCase())};
try{Object.defineProperty(document,'body',{configurable:true,get:function(){return document.getElementById('aero-root')}});Object.defineProperty(document,'head',{configurable:true,get:function(){return document.getElementById('aero-root')}})}catch(e){}
})();
window.__aeroBoot=async function(){
  if(location.protocol==='file:')throw new Error('Proxy needs http(s)');
  const B=location.pathname.replace(/[^\/]*$/,'');
  const reg=await navigator.serviceWorker.register(B+'sw.js',{scope:B});
  await navigator.serviceWorker.ready;
  if(!navigator.serviceWorker.controller){
    await new Promise(r=>{
      const tm=setTimeout(r,6000);
      const li=()=>{clearTimeout(tm);r()};
      navigator.serviceWorker.addEventListener('controllerchange',li,{once:true});
    });
  }
  if(!navigator.serviceWorker.controller)throw new Error('SW failed to control page');
};
